mapper.update:
UPDATE KNOWLEDGE_INGESTION_JOB
SET REVISION=#{revision}, STATUS=#{status}, SINKS_JSON=#{sinksJson}, REQUIRED_SINKS_JSON=#{requiredSinksJson},
    ERROR_TEXT=#{errorText}, UPDATED_AT=#{updatedAt}, RETRY_COUNT=#{retryCount}, NEXT_RETRY_AT=#{nextRetryAt}, ERROR_CODE=#{errorCode}, FAILED_STAGE=#{failedStage}, LEASE_OWNER=#{leaseOwner}, LEASE_UNTIL=#{leaseUntil}, PREPARATION_JSON=#{preparationJson}
WHERE DELETED=0 AND (TENANT_ID=#{tenantId} AND JOB_ID=#{jobId} AND REVISION=#{revision2})
  AND (PREPARATION_JSON IS NULL OR PREPARATION_JSON=#{preparationJson}
       OR PREPARATION_JSON=#{pendingPreparationJson})

mapper.select:
SELECT * FROM KNOWLEDGE_INGESTION_JOB
WHERE DELETED=0 AND (STATUS IN ('RECEIVED','PROCESSING') AND LEASE_OWNER IS NULL) ORDER BY UPDATED_AT
LIMIT #{limit}
